function esc(v){return String(v==null?'':v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');}
function arr(v){return Array.isArray(v)?v:[];}
function num(v){var n=parseFloat(v);return isFinite(n)?n:0;}
function enc(v){return encodeURIComponent(String(v==null?'':v));}
function safeDate(v){var d=v?new Date(v):null;return d&&!isNaN(d.getTime())?d:null;}
function dayStart(){var d=new Date();d.setHours(0,0,0,0);return d;}
function relDays(v){var d=safeDate(v);if(!d)return null;d.setHours(0,0,0,0);return Math.round((d-dayStart())/86400000);}
function since(v){var d=safeDate(v);return d?Math.max(0,Math.floor((Date.now()-d.getTime())/86400000)):null;}
function dateText(v){var d=safeDate(v);return d?d.toLocaleDateString('sq-AL',{day:'2-digit',month:'short',year:'numeric'}):'—';}
function money(v,c){return num(v).toLocaleString('de-DE',{minimumFractionDigits:2,maximumFractionDigits:2})+' '+(c||'EUR');}
function greet(){var h=new Date().getHours();return h<12?'Mirëmëngjes':h<18?'Mirëdita':'Mirëmbrëma';}
function hash(s){s=String(s||'');var h=2166136261;for(var i=0;i<s.length;i++){h^=s.charCodeAt(i);h+=(h<<1)+(h<<4)+(h<<7)+(h<<8)+(h<<24);}return(h>>>0).toString(36);}
function activeProject(p){var s=String((p&&p.status)||'').toLowerCase();return ['mbyllur','fituar','humbur','arkivuar','closedwon','closedlost','cancelled','realizuar'].indexOf(s)<0;}
function stageName(id){return({rfq_in:'Kërkesa e klientit',technical_review:'Verifikimi teknik',supplier_selection:'Zgjedhja e prodhuesit',pricing:'Përcaktimi i çmimit',client_offer:'Oferta & konfirmimi',commercial:'Përpunimi komercial',production_control:'Koordinimi i prodhimit',factory_audit:'Auditimi i uzinës',transport:'Transporti & dërgesa'})[id]||'Në pritje';}
function statusInfo(s){s=String(s||'pritje').toLowerCase();if(['aktiv','fituar','closedwon','ne pune','në punë','realizuar'].indexOf(s)>-1)return{label:s==='fituar'||s==='closedwon'?'Fituar':s==='realizuar'?'Realizuar':'Aktiv',c:GREEN,bg:GREEN_SOFT};if(['humbur','closedlost','cancelled'].indexOf(s)>-1)return{label:'Humbur',c:RED,bg:RED_SOFT};if(['ofertim','oferte','ofertë','negociata'].indexOf(s)>-1)return{label:'Ofertim',c:AMBER,bg:AMBER_SOFT};return{label:s&&s!=='pritje'?s.charAt(0).toUpperCase()+s.slice(1):'Në pritje',c:BLUE,bg:BLUE_SOFT};}
async function db(path,method,body){if(typeof window.supaFetch!=='function')throw new Error('Databaza nuk është gati.');return window.supaFetch(path,method,body);}
async function q(path){try{return arr(await db(path));}catch(e){console.warn('PRISTEEL workspace query:',path,e);return[];}}
function setActiveProject(id){window.__pstCurrentProjectId=String(id||'');window._curProjId=String(id||'');var s=document.getElementById('global-proj');if(s)s.value=String(id||'');}
function toast(text,error){var old=document.getElementById('pst-ws-toast');if(old)old.remove();var e=document.createElement('div');e.id='pst-ws-toast';e.className=error?'error':'';e.textContent=text;document.body.appendChild(e);setTimeout(function(){if(e.parentNode)e.remove();},5200);}

